import { cacheLife, cacheTag } from 'next/cache'

import { getAllProducts } from '@/lib/db'

export type Product = {
  id: number
  name: string
  price: number
}

export type Catalog = {
  products: Product[]
  refreshedAt: string
}

/**
 * Cached catalog read. Every view that needs product data should call this so a
 * single cache entry — tagged `"products"` — backs the whole catalog.
 *
 * `cacheLife('max')` keeps the entry around indefinitely: browsing never pays for
 * a database round trip, and freshness comes from invalidation (see
 * `revalidateTag('products', 'max')` in the sync action) rather than from a TTL.
 */
export async function getProducts(): Promise<Catalog> {
  'use cache'
  cacheTag('products')
  cacheLife('max')

  const products = await getAllProducts()

  return {
    products,
    refreshedAt: new Date().toISOString(),
  }
}

/**
 * Pulls the latest pricing/inventory/availability from the upstream ERP/PIM.
 *
 * A real sync walks thousands of SKUs, so this must never run on the request
 * path — callers hand it to `after()` so the admin's response isn't held open.
 */
export async function syncCatalogFromUpstream(): Promise<void> {
  // Stand-in for the upstream pull + write-back into our own store.
  await new Promise((resolve) => setTimeout(resolve, 2000))
}

