import { revalidateTag } from 'next/cache'
import { after } from 'next/server'

import { getProducts, syncCatalogFromUpstream } from '@/lib/products'

export default async function Page() {
  const { products, refreshedAt } = await getProducts()

  async function syncCatalog() {
    'use server'

    // The ERP/PIM pull can touch thousands of SKUs, so it runs after the response
    // is sent instead of holding the admin's form submission open.
    after(async () => {
      await syncCatalogFromUpstream()

      // Stale-while-revalidate: entries tagged `"products"` are marked stale, so
      // the next request to any view reading the catalog is served the existing
      // list while a fresh one is computed in the background. Using the `'max'`
      // profile (rather than `updateTag`) is what keeps the admin from ever
      // blocking on a freshly recomputed catalog.
      revalidateTag('products', 'max')
    })
  }

  return (
    <div style={{ fontFamily: 'system-ui, sans-serif', padding: '2rem', maxWidth: 720 }}>
      <h1>Product catalog</h1>

      <form action={syncCatalog} style={{ margin: '1.5rem 0' }}>
        <button type="submit">Sync latest catalog</button>
        <p style={{ color: '#666', fontSize: '0.875rem' }}>
          Sync runs in the background. The list below may be briefly stale and will
          pick up upstream changes shortly after.
        </p>
      </form>

      <table style={{ borderCollapse: 'collapse', width: '100%' }}>
        <thead>
          <tr>
            <th style={{ textAlign: 'left', borderBottom: '1px solid #ddd', padding: '0.5rem' }}>
              SKU
            </th>
            <th style={{ textAlign: 'left', borderBottom: '1px solid #ddd', padding: '0.5rem' }}>
              Name
            </th>
            <th style={{ textAlign: 'right', borderBottom: '1px solid #ddd', padding: '0.5rem' }}>
              Price
            </th>
          </tr>
        </thead>
        <tbody>
          {products.map((product) => (
            <tr key={product.id}>
              <td style={{ borderBottom: '1px solid #f0f0f0', padding: '0.5rem' }}>{product.id}</td>
              <td style={{ borderBottom: '1px solid #f0f0f0', padding: '0.5rem' }}>
                {product.name}
              </td>
              <td
                style={{
                  borderBottom: '1px solid #f0f0f0',
                  padding: '0.5rem',
                  textAlign: 'right',
                }}
              >
                ${product.price}
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <p style={{ color: '#666', fontSize: '0.875rem' }}>
        Catalog data cached as of {refreshedAt}
      </p>
    </div>
  )
}

